themes.css:
/* Cinema — a film title sequence. The hero is a full-screen still with the name set in big serif type,
   section titles are credits, experience is a credit roll, and projects scroll sideways like a film strip. */

:root[data-style="cinema"] {
  --font-display: 'Instrument Serif', 'Times New Roman', serif;
  --font-body: 'Instrument Sans', system-ui, sans-serif;
  --radius: 3px; --radius-sm: 3px; --radius-pill: 999px;
  --maxw: 1040px; --section-pad: clamp(4.5rem, 11vw, 9rem); --nav-h: 60px; --gutter: max(1.25rem, calc((100vw - 1100px) / 2));
}
:root[data-style="cinema"][data-mode="dark"] {
  --bg: #0a0a0b; --bg-alt: #0a0a0b; --surface: #141416; --surface-2: #1b1b1e; --border: #34343a;
  --text: #d6d6d2; --text-2: #a2a29d; --heading: #f6f4ee;
  --accent: #f0c15a; --accent-ink: #14110a;
}
:root[data-style="cinema"][data-mode="light"] {
  --bg: #f7f7f5; --bg-alt: #f7f7f5; --surface: #ffffff; --surface-2: #ece9e4; --border: #c8c8c2;
  --text: #26262a; --text-2: #55555a; --heading: #0c0c0e;
  --accent: #b3261e; --accent-ink: #ffffff;
}

[data-style="cinema"] body { font-size: 1.02rem; }
[data-style="cinema"] .section { background: transparent; }
[data-style="cinema"] .site-nav { background: color-mix(in srgb, var(--bg) 62%, transparent); border-bottom: 0; }
[data-style="cinema"] .brand { font-family: var(--font-display); font-weight: 400; font-size: 1.35rem; }
[data-style="cinema"] .brand-mark { background: transparent; color: var(--accent-text); border: 1px solid var(--accent-text); border-radius: 50%; min-width: 2.2rem; width: 2.2rem; height: 2.2rem; padding: 0; font-size: .72rem; }
[data-style="cinema"] .nav-links a { font-weight: 500; }
[data-style="cinema"] .btn { border-radius: 999px; }
[data-style="cinema"] .icon-btn { border-radius: 50%; }

/* ── hero: full-screen still, text at the bottom on a fade ── */
[data-style="cinema"] .hero { position: relative; display: flex; align-items: flex-end; min-height: calc(100vh - var(--nav-h)); min-height: calc(100svh - var(--nav-h)); margin-top: calc(-1 * var(--nav-h)); padding: calc(var(--nav-h) + 3rem) 0 clamp(2.5rem, 7vw, 5rem); overflow: hidden; }
[data-style="cinema"] .hero-inner { display: block; width: 100%; }
[data-style="cinema"] .hero-text { position: relative; z-index: 2; max-width: 52rem; }
[data-style="cinema"] .hero-photo { position: absolute; inset: 0; z-index: 0; width: 100%; max-width: none; aspect-ratio: auto; border-radius: 0; background: var(--surface); }
[data-style="cinema"] .hero-photo img { object-position: center 18%; opacity: .95; }
[data-style="cinema"] .hero-photo::after { content: ''; position: absolute; inset: 0; background: linear-gradient(to top, var(--bg) 6%, color-mix(in srgb, var(--bg) 78%, transparent) 38%, color-mix(in srgb, var(--bg) 8%, transparent) 78%, color-mix(in srgb, var(--bg) 40%, transparent) 100%); }
[data-style="cinema"] .hero-photo--mono { background: var(--surface); color: color-mix(in srgb, var(--heading) 7%, transparent); font-family: var(--font-display); font-size: min(60vw, 52rem); font-weight: 400; align-content: center; }
[data-style="cinema"] .hero-kicker { color: var(--accent-text); font-weight: 500; font-size: 1rem; }
[data-style="cinema"] .hero-name { font-weight: 400; font-size: clamp(3.6rem, 12.5vw, 10.5rem); line-height: .86; letter-spacing: -.035em; animation: cinema-rise 1.1s cubic-bezier(.2, .7, .2, 1) both; }
[data-style="cinema"] .hero-role { margin-top: 1.3rem; font-family: var(--font-display); font-style: italic; font-weight: 400; font-size: clamp(1.4rem, 3vw, 2.1rem); color: var(--heading); }
[data-style="cinema"] .caret { width: .06em; }
[data-style="cinema"] .hero-bio { color: var(--text); max-width: 46ch; }
[data-style="cinema"] .badge { background: color-mix(in srgb, var(--bg) 60%, transparent); border-color: var(--border); color: var(--heading); backdrop-filter: blur(6px); }
[data-style="cinema"] .hero-stats { gap: 1rem 3rem; }
[data-style="cinema"] .hero-stats dd { font-family: var(--font-display); font-weight: 400; font-size: 2.8rem; }
[data-style="cinema"] .hero-stats dt { color: var(--text); }
[data-style="cinema"] .btn--primary { border-radius: 999px; }
[data-style="cinema"] .social { border-radius: 50%; background: color-mix(in srgb, var(--bg) 60%, transparent); }
@keyframes cinema-rise { from { opacity: 0; transform: translateY(.3em); } to { opacity: 1; transform: none; } }

/* ── section titles are credits: a line, the title, a line ── */
[data-style="cinema"] .section-inner { max-width: var(--maxw); }
[data-style="cinema"] .sec-title { display: flex; align-items: center; gap: clamp(1rem, 3vw, 2rem); margin-bottom: clamp(2.2rem, 5vw, 3.6rem); font-weight: 400; font-style: italic; font-size: clamp(2.6rem, 7vw, 5rem); letter-spacing: -.03em; justify-content: center; text-align: center; }
[data-style="cinema"] .sec-title::before, [data-style="cinema"] .sec-title::after { content: ''; flex: 1; height: 1px; background: var(--border); }

/* ── projects: a film strip that scrolls sideways ── */
[data-style="cinema"] .section--projects .section-inner { max-width: none; padding: 0 var(--gutter); }
[data-style="cinema"] .proj-grid { display: flex; gap: 1.4rem; margin: 0 calc(-1 * var(--gutter)); padding: 0 var(--gutter) 1.4rem; overflow-x: auto; scroll-snap-type: x mandatory; scroll-padding-inline: var(--gutter); scrollbar-width: thin; scrollbar-color: var(--border) transparent; }
[data-style="cinema"] .proj-card { flex: 0 0 min(80vw, 430px); scroll-snap-align: start; background: transparent; border: 0; border-radius: 0; }
[data-style="cinema"] .proj-img { aspect-ratio: 4 / 3; border-radius: 3px; outline: 1px solid var(--border); outline-offset: 6px; margin: 6px 6px 0; }
[data-style="cinema"] .proj-body { padding: 1.6rem 6px 0; }
[data-style="cinema"] .proj-body h3 { font-family: var(--font-display); font-weight: 400; font-size: 2rem; letter-spacing: -.02em; }
[data-style="cinema"] .proj-body p { color: var(--text); }
[data-style="cinema"] .proj-card--noimg { border-top: 1px solid var(--border); }

/* ── experience: a credit roll (dates left, details right) ── */
[data-style="cinema"] .timeline { border: 0; padding: 0; gap: 0; }
[data-style="cinema"] .tl-item { display: grid; grid-template-columns: minmax(7rem, 11rem) minmax(0, 1fr); column-gap: 2rem; padding: 1.8rem 0; border-top: 1px solid var(--border); }
[data-style="cinema"] .tl-item::before { display: none; }
[data-style="cinema"] .tl-head { display: contents; }
[data-style="cinema"] .tl-period { grid-column: 1; grid-row: 1 / span 3; margin: 0; font-family: var(--font-display); font-style: italic; font-size: 1.3rem; color: var(--accent-text); }
[data-style="cinema"] .tl-role { grid-column: 2; font-weight: 400; font-size: 1.9rem; letter-spacing: -.02em; }
[data-style="cinema"] .tl-org { grid-column: 2; margin-top: .2rem; }
[data-style="cinema"] .tl-bullets { grid-column: 2; }
[data-style="cinema"] .tl-bullets li::before { border-radius: 50%; background: var(--accent); }
@media (max-width: 700px) { [data-style="cinema"] .tl-item { grid-template-columns: 1fr; } [data-style="cinema"] .tl-period, [data-style="cinema"] .tl-role, [data-style="cinema"] .tl-org, [data-style="cinema"] .tl-bullets { grid-column: 1; grid-row: auto; } [data-style="cinema"] .tl-period { margin-bottom: .4rem; } }

/* ── everything else: quiet and ruled ── */
[data-style="cinema"] .edu-item, [data-style="cinema"] .cert-card, [data-style="cinema"] .award, [data-style="cinema"] .link-card, [data-style="cinema"] .pub { background: transparent; border-color: var(--border); }
[data-style="cinema"] .edu-info h3 { font-family: var(--font-display); font-weight: 400; font-size: 1.7rem; letter-spacing: -.02em; }
[data-style="cinema"] .chip { background: transparent; }
[data-style="cinema"] .tags li { background: transparent; border: 1px solid var(--border); color: var(--text); font-weight: 500; }
[data-style="cinema"] .skill-group h3 { font-family: var(--font-display); font-style: italic; font-weight: 400; font-size: 1.5rem; color: var(--heading); }
[data-style="cinema"] .pub-year { font-family: var(--font-display); font-weight: 400; font-size: 1.5rem; color: var(--accent-text); }
[data-style="cinema"] .link-icon, [data-style="cinema"] .ci-icon { background: transparent; border: 1px solid var(--border); border-radius: 50%; }
[data-style="cinema"] .contact-form { background: var(--surface); border-color: var(--border); }
[data-style="cinema"] .contact-form h3 { font-family: var(--font-display); font-weight: 400; font-size: 1.8rem; }
[data-style="cinema"] .site-footer { text-align: center; }
[data-style="cinema"] .footer-inner { justify-content: center; }

/* Bento — the whole page is a grid of tiles in different sizes, each section its own colour block,
   with a floating pill for navigation. Nothing is a long column. */

:root[data-style="bento"] {
  --font-display: 'Bricolage Grotesque', system-ui, sans-serif;
  --font-body: 'DM Sans', system-ui, sans-serif;
  --radius: 22px; --radius-sm: 14px; --radius-pill: 999px;
  --maxw: 1180px; --card-pad: 1.2rem; --nav-h: 58px;
}
:root[data-style="bento"][data-mode="light"] {
  --bg: #e8eaf2; --bg-alt: #e8eaf2; --surface: #ffffff; --surface-2: #f1f2f8; --border: #d6d9e6;
  --text: #25263a; --text-2: #55576c; --heading: #0e0f1a;
  --accent: #5b3df5; --accent-ink: #ffffff;
  --t1: #e4dfff; --t2: #d6f2e4; --t3: #ffe3d2; --t4: #d6e9ff;
}
:root[data-style="bento"][data-mode="dark"] {
  --bg: #08090d; --bg-alt: #08090d; --surface: #14161d; --surface-2: #1c1f28; --border: #272a36;
  --text: #d4d7e4; --text-2: #9ea2b8; --heading: #ffffff;
  --accent: #a99dff; --accent-ink: #0d0a24;
  --t1: #1d1a3d; --t2: #0f2a20; --t3: #301d14; --t4: #10233a;
}

/* ── the grid ── */
[data-style="bento"] main { max-width: var(--maxw); margin: 14px auto 0; padding: 0 12px; display: grid; grid-template-columns: repeat(12, minmax(0, 1fr)); gap: 14px; grid-auto-flow: dense; }
[data-style="bento"] .section { padding: clamp(1.3rem, 2.6vw, 2rem); background: var(--surface); border-radius: 30px; grid-column: span 12; min-width: 0; }
[data-style="bento"] .section-inner { max-width: none; padding: 0; }
[data-style="bento"] .sec-title { margin: 0 0 1.4rem; font-size: 1.3rem; font-weight: 700; letter-spacing: -.02em; }
[data-style="bento"] .sec-title::before { content: ''; display: inline-block; width: .6em; height: .6em; margin-right: .55em; border-radius: 50%; background: var(--accent); vertical-align: .05em; }
[data-style="bento"] .section--about { grid-column: span 7; background: var(--t1); }
[data-style="bento"] .section--experience { grid-column: span 5; }
[data-style="bento"] .section--skills { grid-column: span 8; background: var(--t2); }
[data-style="bento"] .section--education { grid-column: span 4; background: var(--t3); }
[data-style="bento"] .section--certifications, [data-style="bento"] .section--learning { grid-column: span 6; background: var(--t4); }
[data-style="bento"] .section--publications, [data-style="bento"] .section--awards, [data-style="bento"] .section--links { grid-column: span 6; }
[data-style="bento"] .section--awards { background: var(--t3); }
[data-style="bento"] .section--links { background: var(--t2); }
[data-style="bento"] .section--contact { background: var(--accent); color: var(--accent-ink); }
@media (max-width: 960px) {
  [data-style="bento"] .section { grid-column: span 12 !important; }
}

/* ── floating pill nav ── */
[data-style="bento"] .site-nav { top: 12px; width: calc(100% - 24px); max-width: calc(var(--maxw) - 24px); margin: 12px auto 0; border: 1px solid var(--border); border-radius: 999px; background: color-mix(in srgb, var(--surface) 82%, transparent); box-shadow: 0 10px 30px -14px rgba(20, 20, 60, .3); }
[data-style="bento"] .nav-inner { padding: 0 .6rem 0 .5rem; }
[data-style="bento"] .brand-mark { border-radius: 50%; }
[data-style="bento"] .nav-links a { padding: .4rem .8rem; border-radius: 999px; }
[data-style="bento"] .nav-links a:hover, [data-style="bento"] .nav-links a[aria-current] { background: var(--surface-2); text-decoration: none; }
[data-style="bento"] .site-nav.nav-compact .nav-links { top: calc(var(--nav-h) + 8px); border: 1px solid var(--border); border-radius: 22px; background: var(--surface); }
[data-style="bento"] .btn { border-radius: 999px; }
[data-style="bento"] .btn--primary:hover { filter: none; transform: translateY(-1px); }
[data-style="bento"] .icon-btn { border-radius: 50%; border-color: transparent; background: var(--surface-2); }

/* ── hero tile ── */
[data-style="bento"] .hero { grid-column: span 12; padding: clamp(1.5rem, 3.4vw, 2.8rem); border-radius: 36px; background: radial-gradient(circle at 100% 0%, var(--t1), transparent 55%), radial-gradient(circle at 0% 100%, var(--t2), transparent 45%), var(--surface); }
[data-style="bento"] .hero-inner { max-width: none; padding: 0; gap: clamp(1.5rem, 4vw, 3.5rem); align-items: center; }
[data-style="bento"] .hero-name { font-size: clamp(2.6rem, 6.4vw, 5.2rem); font-weight: 800; letter-spacing: -.045em; line-height: .96; }
[data-style="bento"] .hero-role { color: var(--accent-text); font-weight: 600; }
[data-style="bento"] .hero-bio { color: var(--text); }
[data-style="bento"] .badge { background: var(--surface); border-color: transparent; color: var(--heading); font-weight: 600; }
[data-style="bento"] .hero-stats { gap: .6rem; }
[data-style="bento"] .hero-stats div { min-width: 7rem; padding: .8rem 1.1rem; border-radius: 20px; background: var(--surface); }
[data-style="bento"] .hero-stats dd { font-size: 1.7rem; font-weight: 800; letter-spacing: -.03em; }
[data-style="bento"] .hero-photo { border-radius: 34px; aspect-ratio: 1; max-width: 400px; transform: rotate(2.5deg); box-shadow: 0 24px 50px -24px rgba(30, 20, 90, .5); border: 6px solid var(--surface); }
[data-style="bento"] .hero-photo--mono { background: var(--accent); color: var(--accent-ink); }
[data-style="bento"] .social { border-radius: 50%; border-color: transparent; background: var(--surface); }

/* ── content inside tiles ── */
[data-style="bento"] .proj-card, [data-style="bento"] .edu-item, [data-style="bento"] .cert-card, [data-style="bento"] .award,
[data-style="bento"] .link-card, [data-style="bento"] .pub, [data-style="bento"] .chip { background: var(--surface); border-color: transparent; }
[data-style="bento"] .section--projects .proj-card { background: var(--surface-2); border-radius: 24px; }
[data-style="bento"] .proj-img { margin: 8px 8px 0; border-radius: 18px; }
[data-style="bento"] .proj-body h3 { letter-spacing: -.02em; }
[data-style="bento"] .tags li { background: var(--surface-2); color: var(--heading); font-weight: 500; }
[data-style="bento"] .section--about .tags li, [data-style="bento"] .section--about .chip { background: var(--surface); }
[data-style="bento"] .timeline { border-left-width: 0; padding-left: 0; gap: .8rem; }
[data-style="bento"] .tl-item { padding: 1.1rem 1.2rem; border-radius: 20px; background: var(--surface-2); }
[data-style="bento"] .tl-item::before { display: none; }
[data-style="bento"] .tl-head { flex-direction: column; gap: .1rem; }
[data-style="bento"] .tl-period { margin-left: 0; order: -1; font-size: .8rem; font-weight: 600; color: var(--accent-text); }
[data-style="bento"] .tl-role { font-size: 1.1rem; letter-spacing: -.01em; }
[data-style="bento"] .facts div { border-bottom-color: color-mix(in srgb, var(--heading) 12%, transparent); }
[data-style="bento"] .cert-logo, [data-style="bento"] .edu-logo { border-radius: 12px; }
[data-style="bento"] .link-icon, [data-style="bento"] .ci-icon { border-radius: 50%; background: var(--surface-2); }
[data-style="bento"] .pub-year { color: var(--accent-text); }
[data-style="bento"] .skill-group h3 { color: var(--heading); }
[data-style="bento"] .site-footer { border: 0; margin-top: 14px; }

/* contact tile is the accent colour */
[data-style="bento"] .section--contact .sec-title, [data-style="bento"] .section--contact .sec-title::before { color: inherit; }
[data-style="bento"] .section--contact .sec-title::before { background: var(--accent-ink); }
[data-style="bento"] .section--contact a, [data-style="bento"] .section--contact .ci-label, [data-style="bento"] .section--contact .prose { color: inherit; }
[data-style="bento"] .section--contact .ci-icon { background: color-mix(in srgb, var(--accent-ink) 18%, transparent); color: inherit; }
[data-style="bento"] .section--contact .contact-form { background: var(--surface); color: var(--text); border: 0; border-radius: 24px; }
[data-style="bento"] .section--contact .contact-form h3 { color: var(--heading); }
[data-style="bento"] .section--contact .contact-form label { color: var(--text-2); }
[data-style="bento"] .section--contact .contact-form input, [data-style="bento"] .section--contact .contact-form textarea { background: var(--surface-2); border-color: transparent; border-radius: 14px; }
[data-style="bento"] .section--contact .contact-form .btn--primary { background: var(--accent); color: var(--accent-ink); }

/* Swiss — a poster. Huge tight headlines, one red circle repeated on purpose, hard black rules,
   and a layout where each section title sits in its own column beside the content. */

:root[data-style="swiss"] {
  --font-display: 'Archivo', 'Helvetica Neue', Arial, sans-serif;
  --font-body: 'Archivo', 'Helvetica Neue', Arial, sans-serif;
  --radius: 0px; --radius-sm: 0px; --radius-pill: 0px;
  --maxw: 1180px; --card-pad: 1.1rem; --section-pad: clamp(3rem, 7vw, 5.5rem);
}
:root[data-style="swiss"][data-mode="light"] {
  --bg: #f5f5f2; --bg-alt: #f5f5f2; --surface: #ffffff; --surface-2: #e9e9e4; --border: #c9c9c2;
  --text: #1c1c1c; --text-2: #4d4d4a; --heading: #0b0b0b;
  --accent: #d02510; --accent-ink: #ffffff;
}
:root[data-style="swiss"][data-mode="dark"] {
  --bg: #0d0d0d; --bg-alt: #0d0d0d; --surface: #181818; --surface-2: #222222; --border: #3a3a3a;
  --text: #dcdcd8; --text-2: #a4a4a0; --heading: #ffffff;
  --accent: #ff5a3c; --accent-ink: #0d0d0d;
}

/* ── frame ── */
[data-style="swiss"] body { letter-spacing: -.005em; }
[data-style="swiss"] .site-nav { background: color-mix(in srgb, var(--bg) 94%, transparent); border-bottom: 3px solid var(--heading); }
[data-style="swiss"] .brand { font-weight: 800; letter-spacing: -.03em; }
[data-style="swiss"] .brand-mark { border-radius: 50%; min-width: 2rem; width: 2rem; padding: 0; font-size: .7rem; }
[data-style="swiss"] .nav-links a { font-weight: 600; color: var(--text); }
[data-style="swiss"] .icon-btn, [data-style="swiss"] .btn { border: 2px solid var(--heading); }
[data-style="swiss"] .icon-btn:hover, [data-style="swiss"] .btn:hover { border-color: var(--accent-text); }

/* ── hero ── */
[data-style="swiss"] .hero { padding: clamp(2rem, 6vw, 4.5rem) 0 clamp(2.5rem, 5vw, 4rem); }
[data-style="swiss"] .hero-inner { grid-template-columns: minmax(0, 1.7fr) minmax(0, 1fr); }
[data-style="swiss"] .hero-kicker { color: var(--text); font-weight: 600; font-size: 1rem; }
[data-style="swiss"] .hero-name { font-weight: 800; font-size: clamp(3rem, 8.4vw, 7.4rem); line-height: .88; letter-spacing: -.055em; }
[data-style="swiss"] .hero-role { color: var(--heading); font-weight: 600; font-size: clamp(1.15rem, 2.2vw, 1.55rem); margin-top: 1.4rem; }
[data-style="swiss"] .hero-bio { color: var(--text); font-size: 1.1rem; max-width: 46ch; }
[data-style="swiss"] .badge { border: 2px solid var(--heading); color: var(--heading); font-weight: 600; }
[data-style="swiss"] .hero-stats { border-top: 3px solid var(--heading); padding-top: 1.1rem; gap: 1rem 3rem; }
[data-style="swiss"] .hero-stats dd { font-size: clamp(2.2rem, 4.4vw, 3.4rem); font-weight: 800; letter-spacing: -.04em; }
[data-style="swiss"] .hero-stats dt { color: var(--text); font-weight: 500; }
[data-style="swiss"] .btn--primary { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); }
[data-style="swiss"] .btn--primary:hover { color: var(--accent-ink); border-color: var(--heading); filter: none; }
[data-style="swiss"] .social { border: 2px solid var(--heading); color: var(--heading); }

/* the circle: the photo is cropped round and a red disc sits behind it, offset */
[data-style="swiss"] .hero-photo { isolation: isolate; position: relative; overflow: visible; border-radius: 50%; aspect-ratio: 1; background: none; max-width: 380px; }
[data-style="swiss"] .hero-photo img { border-radius: 50%; filter: grayscale(1) contrast(1.05); }
[data-style="swiss"] .hero-photo::before { content: ''; position: absolute; inset: 0; z-index: -1; border-radius: 50%; background: var(--accent); transform: translate(8%, 8%); animation: swiss-pop .7s cubic-bezier(.2, .8, .2, 1) both; }
[data-style="swiss"] .hero-photo--mono { background: var(--heading); color: var(--bg); }
@keyframes swiss-pop { from { transform: translate(0, 0) scale(.82); opacity: 0; } to { transform: translate(8%, 8%) scale(1); opacity: 1; } }
@media (max-width: 820px) { [data-style="swiss"] .hero-photo { max-width: 200px; } [data-style="swiss"] .hero-name { font-size: clamp(2.8rem, 15vw, 5rem); } }

/* ── sections: title in the left column, content on the right, a black rule on top ── */
