[data-style="swiss"] .proj-body p, [data-style="swiss"] .tl-bullets, [data-style="swiss"] .cert-text span, [data-style="swiss"] .award-text span, [data-style="swiss"] .link-text span, [data-style="swiss"] .pub-text span { color: var(--text); }
