[data-style="bloom"] .tl-item { padding: 1.4rem 1.6rem; border-radius: var(--radius); background: var(--surface); }
[data-style="bloom"] .tl-item::before { display: none; }
[data-style="bloom"] .tl-item:nth-child(4n+1) { background: var(--p1); } [data-style="bloom"] .tl-item:nth-child(4n+2) { background: var(--p2); }
[data-style="bloom"] .tl-item:nth-child(4n+3) { background: var(--p3); } [data-style="bloom"] .tl-item:nth-child(4n+4) { background: var(--p4); }
[data-style="bloom"] .tl-period { padding: .15rem .7rem; border-radius: var(--radius-pill); background: color-mix(in srgb, var(--surface) 70%, transparent); }
[data-style="bloom"] .chip { background: var(--surface); border-color: transparent; box-shadow: var(--shadow); }
[data-style="bloom"] .skill-group h3 { color: var(--heading); }
[data-style="bloom"] .contact-form { background: var(--surface); }
[data-style="bloom"] .contact-form input, [data-style="bloom"] .contact-form textarea { border-radius: 14px; background: var(--bg); }
[data-style="bloom"] .site-footer { border-top: 0; text-align: center; }
[data-style="bloom"] .footer-inner { justify-content: center; flex-direction: column; }
[data-style="bloom"] .hero-role, [data-style="bloom"] .hero-name { text-wrap: balance; }

/* Terminal — monospace, shell windows */
:root[data-style="terminal"] {
  --font-display: 'JetBrains Mono', ui-monospace, monospace; --font-body: 'JetBrains Mono', ui-monospace, monospace; --font-mono: 'JetBrains Mono', ui-monospace, monospace;
  --radius: 6px; --radius-sm: 4px; --radius-pill: 4px; --maxw: 1040px; --card-pad: 1.2rem; --section-pad: clamp(3rem, 6vw, 5rem);
}
:root[data-style="terminal"][data-mode="dark"] {
  --bg: #090e0b; --bg-alt: #090e0b; --surface: #0e1511; --surface-2: #14201a; --border: #1f3a2a;
  --text: #a9c8b4; --text-2: #78957f; --heading: #d9f7e2; --accent: #4ade80; --accent-ink: #04140a; --accent-text: var(--accent); --warn: #fbbf24;
}
:root[data-style="terminal"][data-mode="light"] {
  --bg: #eef2ec; --bg-alt: #eef2ec; --surface: #f9fbf7; --surface-2: #e1e9df; --border: #bccdbe;
  --text: #28402f; --text-2: #55705c; --heading: #10241a; --accent: #0a7d3b; --accent-ink: #f3fff7; --accent-text: var(--accent); --warn: #a16207;
}
[data-style="terminal"] body { font-size: .94rem; line-height: 1.7; }
[data-style="terminal"] body::after { content: ''; position: fixed; inset: 0; pointer-events: none; z-index: 100; background: repeating-linear-gradient(0deg, rgba(0, 0, 0, .06) 0 1px, transparent 1px 3px); opacity: .5; }
[data-style="terminal"][data-mode="light"] body::after { opacity: .12; }
[data-style="terminal"] h1, [data-style="terminal"] h2, [data-style="terminal"] h3 { font-weight: 700; letter-spacing: -.01em; }
[data-style="terminal"] .site-nav { background: var(--bg); backdrop-filter: none; }
[data-style="terminal"] .brand { font-weight: 500; }
[data-style="terminal"] .brand-mark { background: transparent; color: var(--accent-text); border: 1px solid var(--accent-text); }
[data-style="terminal"] .brand-name::before { content: '~/'; color: var(--accent-text); }
[data-style="terminal"] .brand-name { text-transform: lowercase; }
[data-style="terminal"] .nav-links a { text-transform: lowercase; font-size: .82rem; }
[data-style="terminal"] .nav-links a::before { content: './'; color: var(--text-2); }
[data-style="terminal"] .nav-links a[aria-current] { color: var(--accent-text); }
[data-style="terminal"] .btn { border-radius: var(--radius-sm); font-weight: 500; }
[data-style="terminal"] .btn::before { content: '$'; color: var(--accent-text); }
[data-style="terminal"] .btn--primary { background: var(--accent); color: var(--accent-ink); }
[data-style="terminal"] .btn--primary::before { color: var(--accent-ink); opacity: .7; }
[data-style="terminal"] .btn--small::before { display: none; }

[data-style="terminal"] .hero-inner { align-items: start; }
[data-style="terminal"] .hero-text { padding: 1.6rem 1.6rem 1.8rem; border: 1px solid var(--border); border-radius: var(--radius); background: var(--surface); position: relative; padding-top: 3.2rem; }
[data-style="terminal"] .hero-text::before { content: ''; position: absolute; left: 1rem; top: 1rem; width: 11px; height: 11px; border-radius: 50%; background: #ff5f56; box-shadow: 18px 0 0 #ffbd2e, 36px 0 0 #27c93f; }
[data-style="terminal"] .hero-kicker { color: var(--text-2); margin-bottom: .4rem; }
[data-style="terminal"] .hero-kicker::before { content: '$ whoami --from'; display: block; color: var(--accent-text); margin-bottom: .2rem; }
[data-style="terminal"] .hero-kicker i { display: none; }
[data-style="terminal"] .hero-name { font-size: clamp(2.2rem, 6vw, 4rem); letter-spacing: -.04em; }
[data-style="terminal"] .hero-role { font-weight: 500; color: var(--warn); }
[data-style="terminal"] .hero-role::before { content: '> '; color: var(--text-2); }
[data-style="terminal"] .hero-bio { font-size: .95rem; }
[data-style="terminal"] .hero-photo { border: 1px solid var(--border); border-radius: var(--radius); max-width: 320px; filter: saturate(.85); }
[data-style="terminal"] .hero-photo:not(.hero-photo--mono) { padding: 6px; background: var(--surface); }
[data-style="terminal"] .hero-photo:not(.hero-photo--mono) img { border-radius: 3px; }
[data-style="terminal"] .hero-stats dd { font-size: 1.7rem; color: var(--accent-text); }
[data-style="terminal"] .badge { text-transform: lowercase; }
[data-style="terminal"] .badge::before { content: '#'; color: var(--accent-text); margin-right: .1rem; }
[data-style="terminal"] .social { border-radius: var(--radius-sm); }

[data-style="terminal"] .section { border-top: 1px dashed var(--border); }
[data-style="terminal"] .section:nth-of-type(even) { background: transparent; }
[data-style="terminal"] .sec-title { font-size: clamp(1.4rem, 3vw, 1.9rem); text-transform: lowercase; color: var(--heading); }
[data-style="terminal"] .sec-title::before { content: '~/'; color: var(--accent-text); }
[data-style="terminal"] .sec-title::after { content: ''; display: inline-block; width: .55em; height: 1em; margin-left: .3em; vertical-align: -.12em; background: var(--accent-text); animation: blink 1.1s steps(1) infinite; }
[data-style="terminal"] .proj-card, [data-style="terminal"] .edu-item, [data-style="terminal"] .contact-form { position: relative; padding-top: 0; }
[data-style="terminal"] .proj-card::before, [data-style="terminal"] .edu-item::before, [data-style="terminal"] .contact-form::before { content: ''; display: block; height: 2rem; border-bottom: 1px solid var(--border); background: var(--surface-2); flex: none; }
[data-style="terminal"] .proj-card::after, [data-style="terminal"] .edu-item::after, [data-style="terminal"] .contact-form::after { content: ''; position: absolute; left: .8rem; top: .7rem; width: 8px; height: 8px; border-radius: 50%; background: #ff5f56; box-shadow: 14px 0 0 #ffbd2e, 28px 0 0 #27c93f; }
[data-style="terminal"] .edu-item { flex-wrap: wrap; padding: 0; } 
[data-style="terminal"] .edu-item::before { flex: 0 0 100%; }
[data-style="terminal"] .edu-logo, [data-style="terminal"] .edu-info { margin: 1.2rem 0 1.3rem 1.2rem; }
[data-style="terminal"] .edu-info { flex: 1; margin-right: 1.2rem; }
[data-style="terminal"] .contact-form { padding: 0 0 1.4rem; } [data-style="terminal"] .contact-form > * { margin-left: 1.3rem; margin-right: 1.3rem; } [data-style="terminal"] .contact-form::before { margin: 0; }
[data-style="terminal"] .contact-form h3 { margin-top: 1rem; }
[data-style="terminal"] .proj-img { border-bottom: 1px solid var(--border); } [data-style="terminal"] .proj-img img { filter: saturate(.8); }
[data-style="terminal"] .proj-body h3::before { content: '$ '; color: var(--accent-text); }
[data-style="terminal"] .cert-card, [data-style="terminal"] .award, [data-style="terminal"] .link-card, [data-style="terminal"] .pub { background: var(--surface); }
[data-style="terminal"] a.cert-card:hover, [data-style="terminal"] a.award:hover, [data-style="terminal"] a.link-card:hover, [data-style="terminal"] a.pub:hover { border-color: var(--accent-text); text-decoration: none; background: var(--surface-2); }
[data-style="terminal"] .tags li { background: transparent; border: 1px solid var(--border); color: var(--text-2); font-weight: 500; }
[data-style="terminal"] .chip { background: transparent; border-radius: var(--radius-sm); }
[data-style="terminal"] .chip--skill::before { content: '['; color: var(--text-2); margin-right: -.3rem; } [data-style="terminal"] .chip--skill::after { content: ']'; color: var(--text-2); margin-left: -.3rem; }
[data-style="terminal"] .chip--skill { border-color: transparent; padding-left: .2rem; padding-right: .2rem; }
[data-style="terminal"] .chip--interests .chip::before, [data-style="terminal"] .chips--interests .chip::before { content: '- '; color: var(--accent-text); }
[data-style="terminal"] .timeline { border-left: 1px dashed var(--border); }
[data-style="terminal"] .tl-item::before { border-radius: 2px; box-shadow: none !important; width: 9px; height: 9px; left: calc(-1.6rem - 5px); }
[data-style="terminal"] .tl-bullets li::before { content: '>'; width: auto; height: auto; background: none; top: 0; color: var(--accent-text); border-radius: 0; }
[data-style="terminal"] .tl-org { color: var(--warn); }
[data-style="terminal"] .link-icon, [data-style="terminal"] .ci-icon { border-radius: var(--radius-sm); }
[data-style="terminal"] .pub-year { color: var(--warn); }
[data-style="terminal"] .site-footer { border-top: 1px dashed var(--border); }
[data-style="terminal"] .site-footer .footer-inner > span::before { content: '$ echo '; color: var(--accent-text); }
